create database CSB;
use CSB;
select * from dbo.cleaned_data_CSB;

update dbo.cleaned_data_CSB
set purchase_frequency_days = REPLACE(purchase_frequency_days, '"', '');

alter table dbo.cleaned_data_CSB
alter column purchase_amount decimal(10,2);

update dbo.cleaned_data_CSB
set review_rating = round(review_rating, 1);

--Q1. What is the total revenue generated by male vs female customers?
select gender, sum(purchase_amount) as Revenue from dbo.cleaned_data_CSB group by gender order by Revenue;

--Q2 Which customer used a discount but still spend more than average purchase amount?
select customer_id, purchase_amount from dbo.cleaned_data_CSB 
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from dbo.cleaned_data_CSB);

--Q3 What are the top 5 products with the highest average review rating?
select top 5 item_purchased, round(avg(review_rating),1) as avg_review_rating from dbo.cleaned_data_CSB 
group by item_purchased order by avg(review_rating) desc;

--Q4 Compare the average purchase amount between between shipping standard and express shipping?
select shipping_type, round(avg(purchase_amount),2) as avg_purchase_amount
from dbo.cleaned_data_CSB
where shipping_type in ('standard','Express')
group by shipping_type;

--Q5 Do subscribed customers spend more? Compare avg spend and total revenue 
--between subscribers and non-subscribers.
select subscription_status,
count(customer_id) total_customers,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from dbo.cleaned_data_CSB
group by subscription_status;

--Q6 Which 5 products have the highest percentage of purchases with discount applied?
select top 5 item_purchased,
round(100 * sum(case when discount_applied = 'Yes' Then 1 else 0 end) / count(*), 2) as discount_rate
from dbo.cleaned_data_CSB
group by item_purchased
order by discount_rate desc;

--Q7 Segment customers into new, Returning and loyal based on their total
-- number of prechases, and show the count of each segment.
with customer_type as (
select customer_id, previous_purchases,
CASE
	When previous_purchases = 1 Then 'New'
	When previous_purchases between 2 and 10 Then 'Returning'
	Else 'Loyal'
	end as customer_segment
from dbo.cleaned_data_CSB
)
select customer_segment, count(*)  as "Number of customers"
from customer_type
group by customer_segment;

--Q8 What are the top 3 most purchased products within each category 
with item_counts as ( 
select category, 
item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from dbo.cleaned_data_CSB
group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <= 3;

--Q9 Are customers who are repeat buyers (more than 5 previous purchases) also like to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from dbo.cleaned_data_CSB
where previous_purchases > 5
group by subscription_status;

--Q10 What is the revenue contribution of each age group?
select age_group,
sum(purchase_amount) as total_revenue
from dbo.cleaned_data_CSB
group by age_group
order by total_revenue desc;